static int IRAM_ATTR esp_mipi_dsi_dma_isr(int irq, FAR void *context,
                                          FAR void *arg)
{
  FAR struct esp_mipi_dsi_priv_s *priv =
    (FAR struct esp_mipi_dsi_priv_s *)arg;
  FAR dw_gdma_dev_t *dev;
  FAR void *next_fb = NULL;
  irqstate_t flags;
  bool transfer_done;
  bool frame_swapped;
  uint32_t status;

  UNUSED(irq);
  UNUSED(context);

  if (priv == NULL || priv->dw_hal.dev == NULL)
    {
      return OK;
    }

  dev = priv->dw_hal.dev;
  flags = spin_lock_irqsave(&priv->dmalock);
  status = dw_gdma_ll_channel_get_intr_status(dev, ESP_MIPI_DSI_DMA_CHAN);
  dw_gdma_ll_channel_clear_intr(dev, ESP_MIPI_DSI_DMA_CHAN, status);
  transfer_done =
    (status & DW_GDMA_LL_CHANNEL_EVENT_DMA_TFR_DONE) != 0 &&
    priv->dma_enabled;

  if (transfer_done)
    {
      next_fb = priv->pending_fb;
      priv->pending_fb = NULL;
    }

  frame_swapped = next_fb != NULL;

  spin_unlock_irqrestore(&priv->dmalock, flags);

  if (!transfer_done)
    {
#ifdef CONFIG_ESPRESSIF_MIPI_CSI
      /* CSI has its own status/error path.  Keep this shared ISR focused on
       * the DSI channel and dispatch CSI only after DSI state is restored. */
      dw_gdma_shared_isr();
#endif
      return OK;
    }

  flags = spin_lock_irqsave(&priv->dmalock);
  if (priv->dma_enabled)
    {
      if (next_fb != NULL && next_fb != priv->fb)
        {
          dw_gdma_ll_lli_set_src_addr(priv->lli_nc,
                                      (uint32_t)(uintptr_t)next_fb);
          dw_gdma_ll_lli_set_src_master_port(priv->lli_nc,
                                             (intptr_t)next_fb);
          priv->fb = next_fb;
        }

      esp_mipi_dsi_dma_restart(priv);
    }

  spin_unlock_irqrestore(&priv->dmalock, flags);

  if (frame_swapped)
    {
      nxsem_post(&priv->fb_done);
    }

#ifdef CONFIG_ESPRESSIF_MIPI_CSI
  /* Re-arm the display channel before servicing CSI.  CSI completion is
   * deferred to LPWORK, so this call only performs short register work. */
  dw_gdma_shared_isr();
#endif

  return OK;
}

