static bool IRAM_ATTR csi_buffer_finished(esp_cam_ctlr_handle_t handle,
                                          FAR esp_cam_ctlr_trans_t *trans,
                                          FAR void *arg)
{
  FAR struct esp_mipi_csi_s *priv = arg;
  irqstate_t flags;
  bool queue_worker = false;
  int index;
  int ret;

  UNUSED(handle);
  index = csi_buffer_index(priv, trans->buffer);
  if (index < 0)
    {
      return false;
    }

  flags = spin_lock_irqsave(&priv->lock);
  priv->frames_completed++;
  if (!priv->capturing || priv->state[index] != CSI_BUFFER_DMA ||
      priv->ready_count >= CSI_DMA_BUFFER_COUNT)
    {
      priv->state[index] = CSI_BUFFER_FREE;
      priv->frames_dropped++;
    }
  else
    {
      priv->state[index] = CSI_BUFFER_READY;
      priv->ready[priv->ready_tail] = index;
      priv->ready_tail = (priv->ready_tail + 1) % CSI_DMA_BUFFER_COUNT;
      priv->ready_count++;
      queue_worker = true;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (queue_worker)
    {
      ret = work_queue(LPWORK, &priv->work, csi_worker, priv, 0);
      if (ret < 0 && ret != -EBUSY)
        {
          flags = spin_lock_irqsave(&priv->lock);
          priv->work_failures++;
          spin_unlock_irqrestore(&priv->lock, flags);
        }
    }

  return false;
}

