      if (priv->state[i] != CSI_BUFFER_COPYING)
        {
          priv->state[i] = CSI_BUFFER_FREE;
        }
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (was_capturing)
    {
      err = esp_cam_ctlr_stop(priv->controller);
    }

  /* Do not use work_cancel_sync here.  V4L2 may call stop_capture from the
   * completion callback running on LPWORK; synchronously cancelling that
   * same work item deadlocks.  Uninit performs the synchronous drain after
   * capture has stopped.
   */

  work_cancel(LPWORK, &priv->work);
  return err == ESP_OK ? OK : csi_error(err);
}

